class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def _insert_helper(node, val):
    if node is None:
        return TreeNode(val)
    if val < node.val:
        node.left = _insert_helper(node.left, val)
    else:
        node.right = _insert_helper(node.right, val)
    return node

def build_bst_from_array(values):
    root = None
    for v in values:
        root = _insert_helper(root, v)
    return root

