public class TreeNode
{
    public int Val;
    public TreeNode? Left;
    public TreeNode? Right;
    public TreeNode(int val) { Val = val; }
}
public static class TreeHarnessBuilder
{
    public static TreeNode? BuildBstFromArray(int[] values)
    {
        TreeNode? root = null;
        foreach (var v in values) root = InsertHelper(root, v);
        return root;
    }
    private static TreeNode InsertHelper(TreeNode? node, int val)
    {
        if (node == null) return new TreeNode(val);
        if (val < node.Val) node.Left = InsertHelper(node.Left, val);
        else node.Right = InsertHelper(node.Right, val);
        return node;
    }
}

